"use client";

import * as React from "react"
import Link from "next/link"

import { CodeIcon, MailIcon } from "@/components/icons"

import { BlogTopBar, Container, TextLink } from "./parts/chrome"
import { formatPostDate, groupPostsByYear, site, socials, type Social } from "./parts/data"

export type BlogHrefs = { home: string; post: string }

const SOCIAL_ICONS = { code: CodeIcon, mail: MailIcon }

function SocialLink({ social }: { social: Social }) {
  const Icon = SOCIAL_ICONS[social.icon]
  return (
    <a
      href={social.href}
      rel="noreferrer"
      className="inline-flex items-baseline gap-1 rounded-xs text-foreground underline decoration-border underline-offset-4 transition-colors duration-150 outline-none hover:decoration-foreground focus-visible:ring-2 focus-visible:ring-ring/50"
    >
      <Icon size={14} className="translate-y-0.5" />
      {social.label}
    </a>
  )
}

/**
 * Personal blog home: a short intro, the social row, then every post grouped by year.
 * Links in the intro are underlined; list rows stay plain until hovered.
 */
export function BlogHome({ hrefs = { home: "/blog", post: "/blog/post" } }: { hrefs?: BlogHrefs }) {
  const years = groupPostsByYear()
  return (
    <div className="bg-background">
      <Container>
        <BlogTopBar homeHref={hrefs.home} />

        <main>
          <h1 className="mb-3 text-base font-medium text-balance">{site.name}</h1>

          <div className="mb-10 flex flex-col gap-3 text-muted-foreground">
            <p className="text-pretty">I write code, and I keep a record of it.</p>
            <p className="text-pretty">Most of what lands here started as a note to myself. Some of it is still useful.</p>
            <p className="text-pretty">
              Start with <TextLink href="#">about this site</TextLink>, or browse{" "}
              <TextLink href="#projects">the projects I&apos;m working on</TextLink>. The posts below are sample content you can
              replace.
            </p>
            <p className="flex flex-wrap items-baseline gap-x-1.5">
              <span>Elsewhere,</span>
              {socials.map((social, i) => (
                <React.Fragment key={social.label}>
                  {i > 0 && <span aria-hidden>{i === socials.length - 1 ? "and" : ","}</span>}
                  <SocialLink social={social} />
                </React.Fragment>
              ))}
            </p>
          </div>

          <div className="flex flex-col gap-8">
            {years.map((group) => (
              <section key={group.year} aria-labelledby={`year-${group.year}`} className="flex flex-col gap-3">
                <h2 id={`year-${group.year}`} className="font-mono text-base font-normal text-balance text-muted-foreground">
                  {group.year}
                </h2>
                <ul className="flex flex-col">
                  {group.posts.map((post) => (
                    <li key={post.slug} className="flex items-baseline gap-4 leading-6">
                      <Link
                        href={hrefs.post}
                        className="min-w-0 wrap-anywhere rounded-xs transition-colors duration-150 outline-none hover:underline focus-visible:ring-2 focus-visible:ring-ring/50"
                      >
                        {post.title}
                      </Link>
                      <time dateTime={post.date} className="ms-auto shrink-0 font-mono text-muted-foreground tabular-nums">
                        {formatPostDate(post.date)}
                      </time>
                    </li>
                  ))}
                </ul>
              </section>
            ))}
          </div>
        </main>
      </Container>
    </div>
  )
}

"use client";

import * as React from "react"
import Link from "next/link"

import { ChevronDownIcon, HomeIcon } from "@/components/icons"
import { Button } from "@/registry/web/ui/button"
import { Menu, MenuContent, MenuItem, MenuTrigger } from "@/registry/web/ui/menu"
import { ThemeToggle } from "@/registry/web/ui/theme-toggle"

import { site } from "./data"

/**
 * The single column the blog lives in: one measure, centred, with room above the title.
 * Keep nested surfaces out of it; this template is text only.
 */
export function Container({ children }: { children: React.ReactNode }) {
  return <div className="mx-auto w-full max-w-reading px-5 pt-12 pb-20">{children}</div>
}

export type Crumb = { label: string; href?: string }

const crumbLink =
  "shrink-0 rounded-xs transition-colors duration-150 outline-none hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring/50"

/** Underlined inline link for the intro. Faint rule at rest, foreground on hover. */
export function TextLink({ href, children }: { href: string; children: React.ReactNode }) {
  const className =
    "rounded-xs font-medium text-foreground underline decoration-border underline-offset-4 transition-colors duration-150 outline-none hover:decoration-foreground focus-visible:ring-2 focus-visible:ring-ring/50"
  if (href.startsWith("/")) {
    return (
      <Link href={href} className={className}>
        {children}
      </Link>
    )
  }
  return (
    <a href={href} className={className} rel="noreferrer">
      {children}
    </a>
  )
}

/** Home, Projects, About and RSS. Home points at the blog index; the rest are placeholders. */
function SiteMenu({ homeHref }: { homeHref: string }) {
  const items = [
    { label: "Home", href: homeHref },
    { label: "Projects", href: "#" },
    { label: "About", href: "#" },
    { label: "RSS", href: "#" },
  ]
  return (
    <Menu>
      <MenuTrigger render={<Button variant="ghost" size="icon-xs" aria-label="More pages" />}>
        <ChevronDownIcon />
      </MenuTrigger>
      <MenuContent>
        {items.map((item) => (
          <MenuItem key={item.label} render={<Link href={item.href} />}>
            {item.label}
          </MenuItem>
        ))}
      </MenuContent>
    </Menu>
  )
}

/**
 * The only chrome on the page: a quiet breadcrumb line with the site menu, and the theme
 * toggle at the far end. Inline `getThemeScript()` in your root `<head>` so the first paint
 * already has the stored theme.
 */
export function BlogTopBar({ homeHref, trail = [] }: { homeHref: string; trail?: Crumb[] }) {
  return (
    <header className="mb-10 flex min-h-7 items-center gap-2 text-sm text-muted-foreground">
      <nav aria-label="Breadcrumb" className="flex min-w-0 items-center gap-2">
        <Link href={homeHref} className={`inline-flex items-center gap-1.5 ${crumbLink}`}>
          <HomeIcon size={14} />
          <span>{site.name}</span>
        </Link>
        <SiteMenu homeHref={homeHref} />
        {trail.map((crumb) => (
          <React.Fragment key={crumb.label}>
            <span aria-hidden className="shrink-0 text-muted-foreground/60">
              /
            </span>
            {crumb.href ? (
              <Link href={crumb.href} className={crumbLink}>
                {crumb.label}
              </Link>
            ) : (
              <span aria-current="page" className="min-w-0 truncate">
                {crumb.label}
              </span>
            )}
          </React.Fragment>
        ))}
      </nav>
      <ThemeToggle variant="ghost" className="ms-auto" />
    </header>
  )
}

/** Replace these with your own posts. Dates are ISO `YYYY-MM-DD` so they sort and group as text. */
export type Post = {
  slug: string
  title: string
  date: string
}

export const author = {
  name: "Mira Okafor",
  role: "design engineer",
  location: "Lisbon",
}

/** The wordmark in the breadcrumb and the title on the index page. */
export const site = { name: author.name }

export const posts: Post[] = [
  { slug: "concentric-corners", title: "Concentric corners", date: "2026-08-19" },
  { slug: "reading-on-small-screens", title: "Reading order on a small screen", date: "2026-02-07" },
  { slug: "markdown-typesetting", title: "Typesetting notes in Markdown", date: "2025-11-14" },
  { slug: "quiet-navigation", title: "Navigation you can find without looking", date: "2025-06-22" },
  { slug: "numbers-that-hold-still", title: "Numbers that hold still", date: "2025-01-09" },
  { slug: "first-principles", title: "Starting from a simple page", date: "2024-11-03" },
  { slug: "keeping-notes", title: "Writing down what I notice", date: "2024-03-12" },
]

export type PostYear = { year: string; posts: Post[] }

const MONTHS = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"]

/** Posts newest first, grouped under the year in their date. */
export function groupPostsByYear(list: Post[] = posts): PostYear[] {
  const groups = new Map<string, Post[]>()
  for (const post of [...list].sort((a, b) => b.date.localeCompare(a.date))) {
    const year = post.date.slice(0, 4)
    const group = groups.get(year)
    if (group) group.push(post)
    else groups.set(year, [post])
  }
  return [...groups].map(([year, group]) => ({ year, posts: group }))
}

/** `08/19`, the short form in the list. */
export function formatPostDate(date: string): string {
  const [, month, day] = date.split("-")
  return `${month}/${day}`
}

/** `19 August 2026`, the line under a post title. */
export function formatLongDate(date: string): string {
  const [year, month, day] = date.split("-")
  return `${Number(day)} ${MONTHS[Number(month) - 1]} ${year}`
}

export type Social = { label: string; href: string; icon: "code" | "mail" }

/** The row of links under the intro. Icons come from the house set, so the labels stay plain. */
export const socials: Social[] = [
  { label: "Code", href: "#", icon: "code" },
  { label: "Mail", href: "#", icon: "mail" },
]

/**
 * The blog routes need no provider: the theme toggle reads and writes the `.dark` class on
 * `<html>`. Inline `getThemeScript()` in your root `<head>` so the first paint is already themed.
 */
export default function BlogLayout({ children }: { children: React.ReactNode }) {
  return children
}

import { BlogHome } from "@/registry/web/templates/blog/blog"

export default function BlogPage() {
  return <BlogHome hrefs={{ home: "/blog", post: "/blog/post" }} />
}

import { BlogPost } from "@/registry/web/templates/blog/post"

export default function BlogPostPage() {
  return <BlogPost hrefs={{ home: "/blog", post: "/blog/post" }} />
}
